#ifndef GUARD_CONSTANTS_CAMERA_H
#define GUARD_CONSTANTS_CAMERA_H

/*
 * Camera modes (#155 run 6, the owner's decision D6). gCameraMode is the
 * mode the room camera update dispatches on. Generated by
 * tools/constants.py; each define is logged with its evidence in
 * docs/analysis/constants.csv.
 */

/* Camera modes - gCameraMode in the stage rooms: the case RoomTaskUpdateCamera (src/room_task.c:69) and the room loaders' first-frame switches dispatch on */
#define CAMERA_MODE_FOLLOW_FOCUS     0 /* the same value in the hub */
#define CAMERA_MODE_FOLLOW_PLAYER    1 /* the same value in the hub */
#define CAMERA_MODE_SLIDE_TO_LOCK    2 /* stage rooms only: the hub's 2 is another mode (see the notes) */
#define CAMERA_MODE_SCROLL_LOCKED    3 /* stage rooms only */
#define CAMERA_MODE_SLIDE_FROM_LOCK  4 /* stage rooms only: the hub's 4 is its hold-anchor mode */
#define CAMERA_MODE_HOLD_ANCHOR      5 /* stage rooms only */

#endif // GUARD_CONSTANTS_CAMERA_H
